def get_div_mult(s, limit):
    divs = [i for i in range(2, s + 1) if s % i == 0]
    mults = [i for i in range(s, limit + 1, s) if i > 1]
    return set(divs + mults)

def solve_winning(f, limit, max_iter=100):
    winning = {f}
    for _ in range(max_iter):
        new_winning = set(winning)
        for s in range(1, limit + 1):
            if s not in winning:
                for y in get_div_mult(s, limit):
                    if y - 1 in winning and y + 1 in winning:
                        new_winning.add(s)
                        break
        if new_winning == winning:
            break
        winning = new_winning
    return winning

for f in range(2, 11):
    print(f"F={f}: {solve_winning(f, 100)}")
